/// <summary>
///  Sale invoice posting class extension
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPostBase))]
internal final class METSalesInvoiceJournalPostBase_Extension
{
}

Method.Source:
/// <summary>
/// This method get called when posting ends
/// </summary>
protected void endPost()
{
    SalesTable salesTable = custInvoiceJour.salesTable();

    next endpost();

    if ((salesTable.ReturnItemNum) || (salesTable.ReturnReasonCodeId && salesTable.METSalesOrderType == METVendParameters::find().SalesOrderType))
    {
        METClaimSOInvoicedBusinessEvent::newFromSalesTable(salesTable).send();
    }        

}
